import{_ as a,o,c as r,a3 as t}from"./chunks/framework.CZBGEXos.js";const n="/manual/img/asistente-ia/inicio.png",s="/manual/img/asistente-ia/matriz-miper.png",h=JSON.parse('{"title":"Asistente IA","description":"","frontmatter":{},"headers":[],"relativePath":"modulos/asistente-ia.md","filePath":"modulos/asistente-ia.md"}'),i={name:"modulos/asistente-ia.md"};function l(d,e,u,c,p,m){return o(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="asistente-ia" tabindex="-1">Asistente IA <a class="header-anchor" href="#asistente-ia" aria-label="Permalink to &quot;Asistente IA&quot;">​</a></h1><p>El <strong>Asistente IA</strong> es un ayudante de prevención de riesgos integrado en la plataforma. Funciona como un chat: le escribes lo que necesitas y te genera documentos técnicos de seguridad listos para revisar, ahorrándote horas de trabajo manual.</p><p>Es especialmente útil para crear los documentos que exige el DS 44 sin partir desde una hoja en blanco: tú das el contexto (un cargo, una actividad), y el asistente propone un borrador que luego revisas, ajustas y apruebas.</p><h2 id="entrar-al-asistente" tabindex="-1">Entrar al Asistente <a class="header-anchor" href="#entrar-al-asistente" aria-label="Permalink to &quot;Entrar al Asistente&quot;">​</a></h2><p>En el menú lateral, haz clic en <strong>Asistente IA</strong>. Verás una conversación donde el asistente te saluda y te explica en qué puede ayudarte.</p><p><img src="'+n+'" alt="Pantalla del Asistente IA con las acciones rápidas y el chat"></p><h2 id="que-puede-hacer" tabindex="-1">Qué puede hacer <a class="header-anchor" href="#que-puede-hacer" aria-label="Permalink to &quot;Qué puede hacer&quot;">​</a></h2><p>El asistente ofrece <strong>acciones rápidas</strong> para las tareas más comunes:</p><ul><li><strong>Matriz MIPER</strong> — genera una matriz de identificación de peligros y evaluación de riesgos <strong>por cargo</strong> específico.</li><li><strong>Matriz de Riesgos</strong> — crea una matriz <strong>para una actividad</strong> determinada.</li><li><strong>Plan de Prevención</strong> — arma un programa de prevención completo.</li><li><strong>Analizar Incidente</strong> — te ayuda a investigar un incidente con un <strong>árbol de causas</strong> según el DS 44.</li><li><strong>Charla 5 Min</strong> — genera el contenido de una charla diaria de seguridad, lista para dictar.</li></ul><h2 id="como-usarlo" tabindex="-1">Cómo usarlo <a class="header-anchor" href="#como-usarlo" aria-label="Permalink to &quot;Cómo usarlo&quot;">​</a></h2><ol><li>Elige una de las <strong>acciones rápidas</strong>, o escribe directamente tu consulta en el campo <em>&quot;Escribe tu consulta sobre prevención de riesgos…&quot;</em>.</li><li>Indica el contexto que te pidan (por ejemplo, el <strong>cargo</strong> para una matriz MIPER, o la <strong>actividad</strong> para una matriz de riesgos).</li><li>El asistente procesará tu pedido (verás <em>&quot;Generando con IA…&quot;</em>) y mostrará el resultado.</li><li>Para matrices, verás una <strong>vista previa visual</strong> del documento generado.</li><li>Revisa el contenido. Si está correcto, <strong>apruébalo</strong>: el documento se <strong>guarda</strong> y queda disponible en el módulo de <a href="/manual/modulos/documentos.html">Documentos</a>.</li></ol><p><img src="'+s+'" alt="Vista previa de una Matriz MIPER generada por el asistente"></p><blockquote><p>⚠️ <strong>Revisa siempre antes de aprobar.</strong> El asistente genera un borrador de muy buena calidad, pero la responsabilidad técnica es tuya. Lee el contenido, ajústalo a la realidad de tu obra y recién entonces apruébalo. La IA es una ayuda, no un reemplazo del criterio del prevencionista.</p></blockquote><h2 id="preguntas-frecuentes" tabindex="-1">Preguntas frecuentes <a class="header-anchor" href="#preguntas-frecuentes" aria-label="Permalink to &quot;Preguntas frecuentes&quot;">​</a></h2><p><strong>¿Lo que genera la IA tiene validez legal por sí solo?</strong> No automáticamente. Es un <strong>borrador asistido</strong>. Debes revisarlo, ajustarlo y aprobarlo bajo tu criterio profesional. Una vez aprobado y firmado, se gestiona como cualquier otro documento de la plataforma.</p><p><strong>¿Dónde quedan los documentos que apruebo?</strong> En el módulo de <a href="/manual/modulos/documentos.html">Documentos</a>, igual que cualquier otro documento. Desde ahí puedes asignarlos para firma.</p><p><strong>Le pedí algo y no me dio lo que esperaba.</strong> Dale más contexto. Mientras más específico seas con el cargo, la actividad o las condiciones de la obra, mejor será el resultado. Puedes pedirle ajustes en el mismo chat.</p><p><strong>¿Quién puede usar el Asistente IA?</strong> Principalmente los roles de gestión que generan documentación técnica (Prevencionista, Administrador, Jefe de Obra). Consulta <a href="/manual/roles/">Roles de Usuario</a>.</p><p><strong>¿Puedo usarlo para analizar un accidente que ya registré?</strong> Sí. La acción <strong>Analizar Incidente</strong> te ayuda a construir el árbol de causas, que complementa el registro del módulo de <a href="/manual/modulos/incidentes.html">Incidentes</a>.</p>',19)])])}const b=a(i,[["render",l]]);export{h as __pageData,b as default};
